const lazy = {};
XPCOMUtils.defineLazyPreferenceGetter(
  lazy,
  "bypassFiltering",
  "mail.inappnotifications.bypass-filtering",
  false
);

const policyPreferences = Object.entries({
  _enabled: "",
  _messageEnabled: "message_",
  _blogEnabled: "blog_",
  _donationEnabled: "donation_",
});

// Disabled because eslint does not see the array notation variable reference.

for (const [property, preference] of policyPreferences) {
  XPCOMUtils.defineLazyPreferenceGetter(
    lazy,
    property,
    `mail.inappnotifications.${preference}enabled`,
    true
  );
}

function versionMatches(pattern, actualVersion) {
  if (!pattern.includes("*")) {
    return pattern === actualVersion;
  }

  const escaped = pattern
    .replaceAll(/[.+?^${}()|[\]\\]/g, "\\$&")
    .replaceAll("*", ".*");

  return new RegExp(`^${escaped}$`).test(actualVersion);
}

